package io.fireflysoftware.common.config.core.authority;

import io.fireflysoftware.common.config.interfaces.documentissuer.DocumentIssuerContracts.Operation;
import io.fireflysoftware.common.config.interfaces.documentissuer.DocumentIssuerContracts.Use;
import io.fireflysoftware.common.config.interfaces.documentissuer.DocumentIssuerContracts.Purpose;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import java.util.function.LongSupplier;
import org.fireflyframework.security.api.domain.*;
import org.fireflyframework.security.spi.*;
import org.fireflyframework.core.transaction.R2dbcOperationBudget;
import org.junit.jupiter.api.Test;
import reactor.core.publisher.Mono;
import reactor.test.StepVerifier;
import static org.junit.jupiter.api.Assertions.*;

/** Controlled SPI boundaries only; no token verification, HTTP or live policy acceptance. */
class DocumentIssuerAuthorizationTest {
    private static final Instant NOW=Instant.parse("2026-10-27T12:00:00Z");
    private final AtomicReference<Instant> now=new AtomicReference<>(NOW);
    private final AtomicLong ticks=new AtomicLong();
    private final LongSupplier nanos=ticks::get;
    private final Clock clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return now.get();}};
    private final DocumentIssuerAuthorization.Scope scope=new DocumentIssuerAuthorization.Scope(DocumentIssuerCodecTest.TENANT,DocumentIssuerCodecTest.ISSUER,DocumentIssuerCodecTest.PUBLICATION,DocumentIssuerCodecTest.ACTION,Operation.PUBLISH,"a".repeat(64),NOW.plusSeconds(60).toEpochMilli());
    private SecurityPrincipal principal(String subject,Map<String,Object> changes){var claims=new HashMap<String,Object>(Map.of("tenant_id",scope.tenantId(),"exp",NOW.plusSeconds(60),"nbf",NOW.minusSeconds(1),"aud",List.of("configuration-document-issuer"),"azp","document-admin"));claims.putAll(changes);return new SecurityPrincipal(subject,"https://identity.example",scope.tenantId(),Set.of(),Set.of("configuration:document-issuers:publish"),claims,NOW,null,Set.of(),Map.of("private","do-not-emit"));}
    private DocumentIssuerAuthorization authority(SecurityContextPort security,PolicyDecisionPort pdp){return new DocumentIssuerAuthorization(security,pdp,"https://identity.example","configuration-document-issuer","tenant_id","azp","document-admin",clock,nanos);}
    @Test void exactOwnerScopeAndDigestReachRealSpiWithoutRawClaims(){var calls=new AtomicInteger();var a=authority(()->Mono.just(principal("checker",Map.of())),(p,action,r,c)->{calls.incrementAndGet();assertEquals("configuration.document-issuer.publish",action);assertTrue(r.contains(scope.publicationId()));assertEquals(scope.intentDigest(),c.get("intentDigest"));assertEquals(scope.tenantId(),c.get("tenantId"));assertFalse(c.containsKey("claims"));assertFalse(c.containsKey("token"));return Mono.just(Decision.permit());});var permit=a.authorize(scope).block();assertNotNull(permit);assertEquals("checker",permit.actor().subject());assertEquals(Duration.ofSeconds(5),permit.budget().remaining());assertEquals(1,calls.get());assertEquals("DocumentIssuerPermit",permit.toString());}
    @Test void noPrincipalOrNoDecisionFailsClosed(){assertThrows(IllegalStateException.class,()->authority(Mono::empty,(p,a,r,c)->Mono.just(Decision.permit())).authorize(scope).block());assertThrows(IllegalStateException.class,()->authority(()->Mono.just(principal("checker",Map.of())),(p,a,r,c)->Mono.empty()).authorize(scope).block());}
    @Test void wrongTenantAudienceClientOrTypedTimeRefusesBeforePdp(){var calls=new AtomicInteger();for(var changes:List.of(Map.<String,Object>of("tenant_id",DocumentIssuerCodecTest.BRAND),Map.<String,Object>of("aud",List.of("other")),Map.<String,Object>of("azp","other"),Map.<String,Object>of("exp",NOW.getEpochSecond()),Map.<String,Object>of("nbf",NOW.plusSeconds(1))))assertThrows(IllegalStateException.class,()->authority(()->Mono.just(principal("checker",changes)),(p,a,r,c)->{calls.incrementAndGet();return Mono.just(Decision.permit());}).authorize(scope).block());assertEquals(0,calls.get());}
    @Test void denyIndeterminateOrUnhandledObligationCannotAuthorize(){for(var decision:List.of(Decision.deny("ordinary denial"),Decision.indeterminate("unavailable"),Decision.permit(List.of(Obligation.of("unsupported",Map.of())))))assertThrows(IllegalStateException.class,()->authority(()->Mono.just(principal("checker",Map.of())),(p,a,r,c)->Mono.just(decision)).authorize(scope).block());}
    @Test void changedCurrentCallerAfterPdpCannotAcquirePermit(){var current=new AtomicReference<>(principal("checker",Map.of()));assertThrows(IllegalStateException.class,()->authority(()->Mono.just(current.get()),(p,a,r,c)->{current.set(principal("other",Map.of()));return Mono.just(Decision.permit());}).authorize(scope).block());}
    @Test void currentPolicyRevocationWithholdsDelivery(){var decision=new AtomicReference<>(Decision.permit());var a=authority(()->Mono.just(principal("checker",Map.of())),(p,op,r,c)->Mono.just(decision.get()));var permit=a.authorize(scope).block();decision.set(Decision.deny("ordinary revocation"));assertThrows(IllegalStateException.class,()->a.reauthorize(permit).block());}
    @Test void reauthorizationNeverRenewsOriginalWallOrMonotonicCap(){var a=authority(()->Mono.just(principal("checker",Map.of())),(p,op,r,c)->Mono.just(Decision.permit()));var permit=a.authorize(scope).block();ticks.set(4_000_000_000L);a.reauthorize(permit).block();assertEquals(Duration.ofSeconds(1),permit.budget().remaining());ticks.set(5_000_000_000L);assertThrows(IllegalStateException.class,()->a.reauthorize(permit).block());}
    @Test void finiteInitialPublisherAndCallerExpiryBoundPdp(){var a=authority(()->Mono.just(principal("checker",Map.of("exp",NOW.plusMillis(100)))),(p,op,r,c)->Mono.never());StepVerifier.withVirtualTime(()->a.authorize(scope)).thenAwait(Duration.ofMillis(101)).expectError(IllegalStateException.class).verify(Duration.ofSeconds(1));}
    @Test void alreadySpentInitialPermissionBudgetDoesNotGrant(){var a=authority(()->Mono.just(principal("checker",Map.of())),(p,op,r,c)->{ticks.set(2_000_000_000L);return Mono.just(Decision.permit());});assertThrows(IllegalStateException.class,()->a.authorize(scope).block());}
    @Test void nativeNarrowingCarriesOriginalCapThroughFinalPdp(){var a=authority(()->Mono.just(principal("checker",Map.of())),(p,op,r,c)->Mono.just(Decision.permit()));var original=a.authorize(scope).block();var cap=R2dbcOperationBudget.observed(NOW,NOW.plusMillis(100),0,Duration.ofSeconds(5),clock,nanos);var narrowed=original.narrow(cap);ticks.set(100_000_000L);assertThrows(IllegalStateException.class,()->a.reauthorize(narrowed).block());}
    @Test void anotherAuthorityInstanceCannotAdoptPrivatePermit(){var a=authority(()->Mono.just(principal("checker",Map.of())),(p,op,r,c)->Mono.just(Decision.permit()));var other=authority(()->Mono.just(principal("checker",Map.of())),(p,op,r,c)->Mono.just(Decision.permit()));assertThrows(IllegalStateException.class,()->other.reauthorize(a.authorize(scope).block()).block());}
    @Test void commitUsesBackendCommitPhaseAndCurrentDenialStopsMutation(){var phases=new ArrayList<>();var decision=new AtomicReference<>(Decision.permit());var a=authority(()->Mono.just(principal("checker",Map.of())),(p,op,r,c)->{phases.add(c.get("phase"));return Mono.just(decision.get());});var permit=a.authorize(scope).block();a.beforeCommit(permit).block();assertEquals(List.of("ADMISSION","COMMIT"),phases);decision.set(Decision.deny("ordinary current denial"));assertThrows(IllegalStateException.class,()->a.beforeCommit(permit).block());}
    SecurityPrincipal consumer(){var p=principal("consumer",Map.of());return new SecurityPrincipal(p.subject(),p.issuer(),p.tenantId(),p.authorities(),Set.of("configuration:document-issuers:current"),p.claims(),p.authTime(),p.acr(),p.amr(),p.attributes());}
    @Test void exactDocumentUseIsVisibleToCurrentOwnerPolicy(){var current=new DocumentIssuerAuthorization.Scope(scope.tenantId(),scope.issuerId(),scope.publicationId(),scope.actionId(),Operation.CURRENT,scope.intentDigest(),null,new Use(Purpose.DEPOSIT_ACCOUNT_ENROLLMENT,"CONTRACT","en-US"));var a=authority(()->Mono.just(consumer()),(p,op,r,c)->{assertEquals("configuration.document-issuer.current",op);assertEquals("CONTRACT",c.get("documentType"));assertEquals("en-US",c.get("locale"));return Mono.just(Decision.permit());});assertNotNull(a.authorize(current).block());}
    @Test void currentCannotFallBackToUnscopedDocumentUse(){var calls=new AtomicInteger();var current=new DocumentIssuerAuthorization.Scope(scope.tenantId(),scope.issuerId(),scope.publicationId(),scope.actionId(),Operation.CURRENT,scope.intentDigest(),null);var a=authority(()->Mono.just(consumer()),(p,op,r,c)->{calls.incrementAndGet();return Mono.just(Decision.permit());});assertThrows(IllegalStateException.class,()->a.authorize(current).block());assertEquals(0,calls.get());}
    @Test void publicationLookupThenResolvedIssuerPolicyKeepOriginalAuthorityWindow(){var resources=new ArrayList<String>();var current=new DocumentIssuerAuthorization.Scope(scope.tenantId(),null,scope.publicationId(),scope.actionId(),Operation.CURRENT,scope.intentDigest(),null,new Use(Purpose.DEPOSIT_ACCOUNT_ENROLLMENT,"CONTRACT","en-US"));var a=authority(()->Mono.just(consumer()),(p,op,r,c)->{resources.add(r);assertFalse(r.contains("null"));return Mono.just(Decision.permit());});var initial=a.authorize(current).block();assertNotNull(initial);assertNull(initial.scope().issuerId());ticks.set(1_000_000_000L);var resolved=initial.resolveIssuer(scope.issuerId());a.reauthorize(resolved).block();assertEquals(scope.issuerId(),resolved.scope().issuerId());assertEquals(Duration.ofSeconds(4),resolved.budget().remaining());assertEquals(initial.observedAt(),resolved.observedAt());assertFalse(resources.getFirst().contains(scope.issuerId()));assertTrue(resources.getLast().contains(scope.issuerId()));}
    @Test void resolvingMetadataCannotReplaceMutationOrKnownIssuerIdentity(){var a=authority(()->Mono.just(principal("checker",Map.of())),(p,op,r,c)->Mono.just(Decision.permit()));assertThrows(IllegalStateException.class,()->a.authorize(scope).block().resolveIssuer(DocumentIssuerCodecTest.BRAND));}
}
